1	{
2	  "name": "stockroom",
3	  "version": "0.0.0",
4	  "private": true,
5	  "type": "module",
6	  "engines": {
7	    "node": ">=24 <25"
8	  },
9	  "scripts": {
10	    "start": "node app.ts"
11	  },
12	  "bin": {
13	    "stockroom": "app.ts"
14	  }
15	}
16

1	#!/usr/bin/env node
2	// stockroom —— 本地多仓库存台账（Node.js 24，TypeScript，无外部运行依赖）
3	
4	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
5	import { join } from 'node:path';
6	
7	const APP_NAME = 'stockroom';
8	const DATA_FILENAME = 'stockroom.json';
9	const DEFAULT_DATA_DIR = '.stockroom';
10	
11	class UsageError extends Error {} // 命令行用法错误 -> 退出码 2
12	class BizError extends Error {} // 业务拒绝 -> 退出码 1
13	class DataError extends Error {} // 数据读取/保存失败 -> 退出码 1
14	
15	type DocType = 'in' | 'out' | 'transfer';
16	type EntryType =
17	  | DocType
18	  | 'count'
19	  | 'arrival'
20	  | 'return'
21	  | 'in-rev'
22	  | 'out-rev'
23	  | 'transfer-rev'
24	  | 'count-rev'
25	  | 'arrival-rev'
26	  | 'return-rev';
27	
28	interface LedgerEntry {
29	  seq: number; // 全局流水序号，即提交顺序
30	  doc: string; // 单据编号（冲销流水此处为冲销单编号）
31	  type: EntryType;
32	  product: string;
33	  wh: string; // 本流水条目变动余量的仓库（到货为采购单收货仓）
34	  qty?: number; // 入库/出库/调拨/到货类流水：恒为正数，方向由类型 / 出入仓决定；盘点类流水不用此字段
35	  before: number;
36	  after: number;
37	  from?: string; // 调拨（或冲销调拨）的调出仓
38	  to?: string; // 调拨（或冲销调拨）的调入仓
39	  po?: string; // 到货/退货流水：所属采购单编号
40	  arr?: string; // 退货（及冲销退货）流水：原到货单编号
41	  orig?: string; // 冲销流水：被冲销的原单编号
42	  expected?: number; // 盘点（及冲销盘点）流水：预期账面量
43	  actual?: number; // 盘点（及冲销盘点）流水：实盘量
44	  diff?: number; // 盘点差额 = 实盘 - 账面（可正、可负、可零）；冲销盘点流水记录原差额
45	}
46	
47	interface DocRecord {
48	  content: Record<string, unknown>; // 规范化业务内容（明细顺序无关）
49	  resultLines: string[]; // 原提交结果，供幂等重放
50	}
51	
52	interface ReversalRecord {
53	  orig: string; // 被冲销的原单编号
54	  resultLines: string[]; // 冲销提交结果，供幂等重放
55	}
56	
57	interface PurchaseRecord {
58	  poId: string;
59	  supplier: string;
60	  wh: string; // 收货仓
61	  ordered: Record<string, number>; // 商品 -> 订购量（合并后，正安全整数）
62	  fromTransfer?: string; // 目的采购单：创建它的采购转单编号（普通登记无此字段）
63	  resultLines: string[]; // 登记结果，供幂等重放
64	}
65	
66	interface PoTransferRecord {
67	  tId: string; // 转单编号（与库存/到货/取消/退货/冲销单共用编号空间）
68	  origPo: string; // 原采购编号
69	  destPo: string; // 新目的采购编号（独立采购编号空间，由本转单创建）
70	  supplier: string; // 目的单供应商
71	  wh: string; // 目的单收货仓
72	  qty: Record<string, number>; // 本次转出：商品 -> 数量（合并后，正安全整数）
73	  resultLines: string[]; // 转单提交结果，供幂等重放
74	}
75	
76	interface ArrivalRecord {
77	  poId: string; // 所属采购单
78	  wh: string; // 采购单收货仓（冗余自采购单，便于校验与展示）
79	  qty: Record<string, number>; // 本次到货：商品 -> 数量（合并后，正安全整数）
80	  resultLines: string[]; // 到货提交结果，供幂等重放
81	}
82	
83	interface CancelRecord {
84	  poId: string; // 所属采购单
85	  qty: Record<string, number>; // 本次取消：商品 -> 数量（合并后，正安全整数）
86	  resultLines: string[]; // 取消提交结果，供幂等重放
87	}
88	
89	interface ReturnRecord {
90	  arrId: string; // 原到货单编号
91	  poId: string; // 所属采购单（冗余自原到货单，便于校验与展示）
92	  wh: string; // 原到货单收货仓（退货从该仓当前余量扣减）
93	  qty: Record<string, number>; // 本次退货：商品 -> 数量（合并后，正安全整数）
94	  resultLines: string[]; // 退货提交结果，供幂等重放
95	}
96	
97	interface ReplenishRule {
98	  min: number; // 下限：预计量不高于此值才触发补货（非负安全整数）
99	  target: number; // 目标：补货缺口 = 目标 - 预计量（非负安全整数，恒大于下限）
100	}
101	
102	interface PlanTransfer {
103	  docId: string; // 调拨子单编号（与库存单据共用编号空间，执行时才占用）
104	  product: string;
105	  from: string; // 调出仓
106	  to: string; // 调入仓（缺货仓）
107	  qty: number; // 冻结的调拨数量（正安全整数）
108	}
109	
110	interface PlanPurchase {
111	  poId: string; // 采购子单编号（独立采购编号空间，执行时才占用）
112	  supplier: string;
113	  wh: string; // 收货仓（缺货仓）
114	  product: string;
115	  qty: number; // 冻结的采购数量（正安全整数）
116	}
117	
118	interface PlanSnapshot {
119	  // 涉及商品（出现在任一调拨/采购子单中的商品）在保存时的全部补货规则
120	  rules: Record<string, Record<string, ReplenishRule>>;
121	  // 这些商品各配置仓在保存时的实存
122	  stock: Record<string, Record<string, number>>;
123	  // 这些商品各配置仓在保存时的待到货合计（精确整数十进制字符串，可超安全整数范围）
124	  pending: Record<string, Record<string, string>>;
125	}
126	
127	interface PlanRecord {
128	  planId: string;
129	  transfers: PlanTransfer[]; // 冻结的调拨子单（按建议顺序：商品、缺货仓、来源仓升序）
130	  purchases: PlanPurchase[]; // 冻结的采购子单（按商品、收货仓升序；零采购不建单）
131	  snapshot: PlanSnapshot; // 保存时冻结的核对快照
132	  status: 'pending' | 'executed';
133	  execResultLines?: string[]; // 已执行方案的落单结果原文，供重放（不再核对、不再生效）
134	  withdrawnBy?: string; // 已撤回方案的撤回请求编号（每案最多成功撤回一次）
135	}
136	
137	interface PlanWithdrawalRecord {
138	  reqId: string; // 撤回请求编号（与库存/到货/取消/退货/转单/冲销单共用编号空间；本身不可冲销）
139	  planId: string; // 被撤回的方案编号
140	  transferRevs: Record<string, string>; // 调拨子单编号 -> 为其指定的冲销单号（逐一对应）
141	  purchaseCancels: Record<string, string>; // 采购子单编号 -> 为其指定的取消单号（逐一对应）
142	  resultLines: string[]; // 撤回提交结果，供幂等重放
143	}
144	
145	interface Store {
146	  version: 1;
147	  products: Record<string, string>; // 编号 -> 名称（编号区分大小写；null 原型，防特殊键串改）
148	  stock: Record<string, Record<string, number>>; // 商品 -> 仓库 -> 余量
149	  entries: LedgerEntry[];
150	  docs: Record<string, DocRecord>; // 入库/出库/调拨/盘点单去重与结果
151	  reversals: Record<string, ReversalRecord>; // 冲销单去重与结果（可冲销到货单、取消单、退货单）
152	  purchases: Record<string, PurchaseRecord>; // 采购单登记（独立编号空间，不改库存）
153	  arrivals: Record<string, ArrivalRecord>; // 到货单去重与结果（与库存单共用编号空间）
154	  cancels: Record<string, CancelRecord>; // 取消单去重与结果（与库存单共用编号空间，不改库存与流水）
155	  returns: Record<string, ReturnRecord>; // 退货单去重与结果（与库存单共用编号空间）
156	  poTransfers: Record<string, PoTransferRecord>; // 采购待收转单去重与结果（与库存单共用编号空间，不改库存与流水）
157	  rules: Record<string, Record<string, ReplenishRule>>; // 补货规则：商品 -> 仓库 -> 下限/目标（每组合唯一）
158	  plans: Record<string, PlanRecord>; // 补货方案（独立编号空间；保存不改库存/采购/流水）
159	  planWithdrawals: Record<string, PlanWithdrawalRecord>; // 方案撤回请求（请求编号与库存单据共用编号空间）
160	}
161	
162	const REV_ENTRY_TYPES = new Set<EntryType>([
163	  'in-rev', 'out-rev', 'transfer-rev', 'count-rev', 'arrival-rev', 'return-rev',
164	]);
165	
166	function nullProto<T extends object>(): T {
167	  return Object.create(null) as T;
168	}
169	
170	function emptyStore(): Store {
171	  return {
172	    version: 1,
173	    products: nullProto(),
174	    stock: nullProto(),
175	    entries: [],
176	    docs: nullProto(),
177	    reversals: nullProto(),
178	    purchases: nullProto(),
179	    arrivals: nullProto(),
180	    cancels: nullProto(),
181	    returns: nullProto(),
182	    poTransfers: nullProto(),
183	    rules: nullProto(),
184	    plans: nullProto(),
185	    planWithdrawals: nullProto(),
186	  };
187	}
188	
189	// ---------- 工具 ----------
190	
191	function isPlainObject(v: unknown): v is Record<string, unknown> {
192	  return typeof v === 'object' && v !== null && !Array.isArray(v);
193	}
194	
195	function isNonNegSafeInt(v: unknown): v is number {
196	  return typeof v === 'number' && Number.isSafeInteger(v) && v >= 0;
197	}
198	
199	function isPosSafeInt(v: unknown): v is number {
200	  return typeof v === 'number' && Number.isSafeInteger(v) && v > 0;
201	}
202	
203	function trimOrThrow(label: string, raw: string): string {
204	  const s = raw.trim();
205	  if (s === '') throw new BizError(`${label}去除首尾空白后不能为空`);
206	  return s;
207	}
208	
209	/** 规范化序列化：对象键排序，保证业务内容比较与明细顺序无关。 */
210	function stableStringify(v: unknown): string {
211	  if (isPlainObject(v)) {
212	    return (
213	      '{' +
214	      Object.keys(v)
215	        .sort()
216	        .map((k) => JSON.stringify(k) + ':' + stableStringify(v[k]))
217	        .join(',') +
218	      '}'
219	    );
220	  }
221	  if (Array.isArray(v)) return '[' + v.map(stableStringify).join(',') + ']';
222	  return JSON.stringify(v);
223	}
224	
225	// ---------- 数据持久化 ----------
226	
227	function dataPath(dataDir: string): string {
228	  return join(dataDir, DATA_FILENAME);
229	}
230	
231	function loadStore(dataDir: string): Store {
232	  let raw: string;
233	  try {
234	    raw = readFileSync(dataPath(dataDir), 'utf8');
235	  } catch (e) {
236	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return emptyStore(); // 尚不存在 -> 空库
237	    throw new DataError(`无法读取数据文件 ${dataPath(dataDir)}：${(e as Error).message}`);
238	  }
239	
240	  let data: unknown;
241	  try {
242	    // JSON.parse 将 "__proto__" 保留为普通自有属性（不设置原型）；随后 validateStore
243	    // 会把全部容器重新装入 null 原型对象，constructor 等特殊键同样安全。
244	    data = JSON.parse(raw);
245	  } catch {
246	    throw new DataError(`数据文件已损坏，无法解析 JSON：${dataPath(dataDir)}（不会作为空库覆盖）`);
247	  }
248	  return validateStore(data);
249	}
250	
251	function validateStore(data: unknown): Store {
252	  const bad = (msg: string): DataError =>
253	    new DataError(`数据文件已损坏或格式不正确（${msg}），拒绝启动以免覆盖原数据`);
254	
255	  if (!isPlainObject(data)) throw bad('根节点不是对象');
256	  if (data.version !== 1) throw bad(`不支持的数据版本：${String(data.version)}`);
257	
258	  // 重新装入 null 原型容器：即使磁盘数据来自普通对象，constructor/__proto__ 等键也安全
259	  const store = emptyStore();
260	
261	  if (!isPlainObject(data.products)) throw bad('products 不是对象');
262	  for (const [id, name] of Object.entries(data.products)) {
263	    if (typeof id !== 'string' || id.trim() === '' || typeof name !== 'string')
264	      throw bad('products 中存在非法编号或名称');
265	    store.products[id] = name;
266	  }
267	
268	  if (!isPlainObject(data.stock)) throw bad('stock 不是对象');
269	  for (const [pid, whs] of Object.entries(data.stock)) {
270	    if (!isPlainObject(whs)) throw bad(`商品 ${pid} 的库存不是对象`);
271	    const whMap = nullProto<Record<string, number>>();
272	    for (const [wh, qty] of Object.entries(whs)) {
273	      if (typeof wh !== 'string' || wh.trim() === '' || !isNonNegSafeInt(qty))
274	        throw bad(`商品 ${pid} 仓库 ${String(wh)} 的余量非法`);
275	      whMap[wh] = qty;
276	    }
277	    store.stock[pid] = whMap;
278	  }
279	
280	  if (!Array.isArray(data.entries)) throw bad('entries 不是数组');
281	  let lastSeq = 0;
282	  for (const e of data.entries as unknown[]) {
283	    if (!isPlainObject(e)) throw bad('存在非法流水条目');
284	    if (!isPosSafeInt(e.seq) || e.seq !== ++lastSeq) throw bad('流水序号不连续');
285	    if (typeof e.doc !== 'string' || e.doc.trim() === '') throw bad('流水缺少单据编号');
286	    const isRev = REV_ENTRY_TYPES.has(e.type as EntryType);
287	    const isOrig =
288	      e.type === 'in' || e.type === 'out' || e.type === 'transfer' || e.type === 'count' ||
289	      e.type === 'arrival' || e.type === 'return';
290	    if (!isRev && !isOrig) throw bad('流水类型非法');
291	    if (typeof e.product !== 'string' || e.product.trim() === '') throw bad('流水缺少商品编号');
292	    if (typeof e.wh !== 'string' || e.wh.trim() === '') throw bad('流水缺少仓库标识');
293	    if (!isNonNegSafeInt(e.before) || !isNonNegSafeInt(e.after)) throw bad('流水余量非法');
294	    if (e.type === 'count' || e.type === 'count-rev') {
295	      if (!isNonNegSafeInt(e.expected) || !isNonNegSafeInt(e.actual))
296	        throw bad('盘点流水账面/实盘量非法');
297	      if (typeof e.diff !== 'number' || !Number.isSafeInteger(e.diff)) throw bad('盘点流水差额非法');
298	      if (e.diff !== e.actual - e.expected) throw bad('盘点流水差额与账面、实盘量不一致');
299	      const applied = e.type === 'count' ? e.diff : -e.diff; // 冲销盘点应用反向差额
300	      if (e.after - e.before !== applied) throw bad('盘点流水差额与前后余量不一致');
301	      if (e.qty !== undefined || e.from !== undefined || e.to !== undefined || e.po !== undefined ||
302	          e.arr !== undefined)
303	        throw bad('盘点流水不应携带数量、调拨、采购或退货字段');
304	    } else {
305	      if (!isPosSafeInt(e.qty)) throw bad('流水数量非法');
306	      if (e.expected !== undefined || e.actual !== undefined || e.diff !== undefined)
307	        throw bad('非盘点流水不应携带盘点字段');
308	      const delta = e.after - e.before;
309	      if (e.type === 'transfer' || e.type === 'transfer-rev') {
310	        if (typeof e.from !== 'string' || e.from.trim() === '' || typeof e.to !== 'string' || e.to.trim() === '')
311	          throw bad('调拨流水缺少调出/调入仓');
312	        if (e.po !== undefined || e.arr !== undefined) throw bad('调拨流水不应携带采购或退货字段');
313	        // 调拨：调入仓增加；冲销调拨：原调入仓扣回、原调出仓补回
314	        const expect = (e.wh === e.to) === (e.type === 'transfer') ? e.qty : -e.qty;
315	        if (delta !== expect) throw bad('流水差额与前后余量不一致');
316	      } else {
317	        if (e.from !== undefined || e.to !== undefined) throw bad('非调拨流水不应携带调拨字段');
318	        // 到货入收货仓、冲销退货补回为增；退货从收货仓扣减、冲销到货扣回为减
319	        const increases =
320	          e.type === 'in' || e.type === 'out-rev' || e.type === 'arrival' || e.type === 'return-rev';
321	        if (delta !== (increases ? e.qty : -e.qty)) throw bad('流水差额与前后余量不一致');
322	        if (e.type === 'arrival' || e.type === 'arrival-rev') {
323	          if (typeof e.po !== 'string' || e.po.trim() === '') throw bad('到货流水缺少采购单编号');
324	          if (e.arr !== undefined) throw bad('到货流水不应携带原到货单字段');
325	        } else if (e.type === 'return' || e.type === 'return-rev') {
326	          if (typeof e.po !== 'string' || e.po.trim() === '') throw bad('退货流水缺少采购单编号');
327	          if (typeof e.arr !== 'string' || e.arr.trim() === '') throw bad('退货流水缺少原到货单编号');
328	        } else if (e.po !== undefined || e.arr !== undefined) {
329	          throw bad('非到货/退货流水不应携带采购或退货字段');
330	        }
331	      }
332	    }
333	    if (isRev) {
334	      if (typeof e.orig !== 'string' || e.orig.trim() === '') throw bad('冲销流水缺少原单编号');
335	    } else if (e.orig !== undefined) {
336	      throw bad('原始单据流水不应携带冲销标记');
337	    }
338	    store.entries.push(e as unknown as LedgerEntry);
339	  }
340	
341	  if (!isPlainObject(data.docs)) throw bad('docs 不是对象');
342	  for (const [docId, rec] of Object.entries(data.docs)) {
343	    if (typeof docId !== 'string' || docId.trim() === '') throw bad('存在非法单据编号');
344	    if (!isPlainObject(rec) || !isPlainObject(rec.content) || !Array.isArray(rec.resultLines))
345	      throw bad(`单据 ${docId} 的去重记录非法`);
346	    if (!rec.resultLines.every((l) => typeof l === 'string')) throw bad(`单据 ${docId} 的结果记录非法`);
347	    const c = rec.content;
348	    if (c.type !== 'in' && c.type !== 'out' && c.type !== 'transfer' && c.type !== 'count')
349	      throw bad(`单据 ${docId} 的业务类型非法`);
350	    if (!isPlainObject(c.items)) throw bad(`单据 ${docId} 的明细非法`);
351	    for (const [pid, item] of Object.entries(c.items)) {
352	      if (pid.trim() === '') throw bad(`单据 ${docId} 存在非法明细`);
353	      if (c.type === 'count') {
354	        if (!isPlainObject(item) || !isNonNegSafeInt(item.expected) || !isNonNegSafeInt(item.actual))
355	          throw bad(`单据 ${docId} 存在非法盘点明细`);
356	      } else if (!isPosSafeInt(item)) {
357	        throw bad(`单据 ${docId} 存在非法明细`);
358	      }
359	    }
360	    if (c.type === 'transfer') {
361	      if (typeof c.from !== 'string' || c.from.trim() === '' || typeof c.to !== 'string' || c.to.trim() === '')
362	        throw bad(`单据 ${docId} 的调拨仓非法`);
363	    } else if (typeof c.wh !== 'string' || c.wh.trim() === '') {
364	      throw bad(`单据 ${docId} 的仓库非法`);
365	    }
366	    store.docs[docId] = rec as unknown as DocRecord;
367	  }
368	
369	  // purchases 为新增字段：合法旧数据没有该字段，按空集合处理。
370	  // 采购单编号独立于库存单据编号空间，允许与入库/到货/冲销单同名。
371	  if (data.purchases !== undefined) {
372	    if (!isPlainObject(data.purchases)) throw bad('purchases 不是对象');
373	    for (const [poId, rec] of Object.entries(data.purchases)) {
374	      if (typeof poId !== 'string' || poId.trim() === '') throw bad('存在非法采购单编号');
375	      if (
376	        !isPlainObject(rec) ||
377	        typeof rec.supplier !== 'string' || rec.supplier.trim() === '' ||
378	        typeof rec.wh !== 'string' || rec.wh.trim() === '' ||
379	        !isPlainObject(rec.ordered) ||
