1139	interface ParsedArgs {
1140	  positionals: string[];
1141	  flags: Record<string, string>;
1142	  multi: Record<string, string[]>;
1143	}
1144	
1145	function parseArgs(
1146	  tokens: string[],
1147	  singles: string[],
1148	  multis: string[] = [],
1149	): ParsedArgs {
1150	  const out: ParsedArgs = { positionals: [], flags: {}, multi: {} };
1151	  const singleSet = new Set(singles);
1152	  const multiSet = new Set(multis);
1153	
1154	  for (let i = 0; i < tokens.length; i++) {
1155	    const tok = tokens[i];
1156	    if (tok.startsWith('--')) {
1157	      let key = tok;
1158	      let value: string | undefined;
1159	      const eq = tok.indexOf('=');
1160	      if (eq >= 0) {
1161	        key = tok.slice(0, eq);
1162	        value = tok.slice(eq + 1);
1163	      }
1164	      if (!singleSet.has(key) && !multiSet.has(key)) throw new UsageError(`未知参数：${tok}`);
1165	      if (value === undefined) {
1166	        if (i + 1 >= tokens.length) throw new UsageError(`参数 ${key} 缺少取值`);
1167	        value = tokens[++i];
1168	      }
1169	      if (multiSet.has(key)) (out.multi[key] ??= []).push(value);
1170	      else if (out.flags[key] !== undefined) throw new UsageError(`参数 ${key} 重复指定`);
1171	      else out.flags[key] = value;
1172	    } else {
1173	      out.positionals.push(tok);
1174	    }
1175	  }
1176	  return out;
1177	}
