1236	function parseNonNegInt(label: string, raw: string): number {
1237	  const s = raw.trim();
1238	  if (!/^\d+$/.test(s)) throw new BizError(`${label}必须为非负安全整数：${raw}`);
1239	  const n = Number(s);
