      reportLines.push(
        `冲销退货 原单=${origId} 原到货单=${arrId} 采购单=${poId} 商品=${pid} @${wh} +${qty}：${before} -> ${after}；有效到货回升至 ${effAfter}/${po.ordered[pid]}，待到货 ${remainingAfter}`,
      );
