4438	/**
4439	 * 整批导入：按列表顺序在同一份草稿上处理各项，后项可见前项生效结果；
4440	 * 任一项失败整批拒绝（此前已保存的单据不撤销，本批任何变动均不落库）。
4441	 * 全部重复时不改写数据。逐项输出编号、首次生效/重复（及重复来源）状态与提交结果。
4442	 */
4443	function runImport(rest: string[], dataDir: string): void {
4444	  const args = parseArgs(rest, ['--file']);
4445	  const file = args.flags['--file'];
4446	  if (file === undefined || args.positionals.length > 0)
4447	    throw new UsageError('用法：import --file <单据列表 JSON 文件>');
4448	
4449	  // 先完整读取并解析文件：文件不可读/解析失败时绝不触碰已提交状态
4450	  const requests = parseImportFile(readImportFile(file));
4451	
4452	  // 参数与文件格式均确认无误后才打开本地数据；损坏数据在此被拒绝且不报告成功
4453	  const store = loadStore(dataDir);
4454	  const ledger = new Ledger(store);
4455	  // 模拟阶段收集输出：只有整批通过并完成保存后才向用户报告，绝不报告部分成功
4456	  const blocks: string[] = [];
4457	  let newCount = 0;
4458	
4459	  requests.forEach((r, i) => {
4460	    const pos = `第 ${i + 1}/${requests.length} 项`;
4461	    // 模拟阶段的业务拒绝同样标注列表位置与原因
4462	    const apply = (): ApplyOutcome => {
4463	      switch (r.kind) {
4464	        case 'doc': return ledger.applyDoc(r.req);
4465	        case 'count': return ledger.applyCount(r.req);
4466	        case 'reverse': return ledger.applyReversal(r.docId, r.orig);
4467	        case 'po': return ledger.applyPurchase(r.req);
4468	        case 'arrival': return ledger.applyArrival(r.req);
4469	        case 'cancel': return ledger.applyCancel(r.req);
4470	        case 'return': return ledger.applyReturn(r.req);
4471	        case 'transfer': return ledger.applyTransfer(r.req);
4472	      }
4473	    };
4474	    let outcome: ApplyOutcome;
4475	    try {
4476	      outcome = apply();
4477	    } catch (e) {
4478	      if (e instanceof BizError) throw new BizError(`第 ${i + 1} 项：${e.message}`);
4479	      throw e;
4480	    }
4481	    const id =
4482	      r.kind === 'reverse' ? r.docId
4483	      : r.kind === 'po' ? r.req.poId
4484	      : r.kind === 'arrival' ? r.req.arrId
4485	      : r.kind === 'cancel' ? r.req.canId
4486	      : r.kind === 'return' ? r.req.retId
4487	      : r.kind === 'transfer' ? r.req.tId
4488	      : r.req.docId;
4489	
4490	    let status: string;
4491	    if (outcome.duplicate) {
4492	      const where = outcome.repeatedFrom === 'batch' ? '（本批此前已出现）' : '（导入前已存在）';
4493	      status = `重复${where}，返回原提交结果，不重新核对库存、不追加流水`;
4494	    } else {
4495	      status = '首次生效';
4496	      newCount++;
4497	    }
4498	    blocks.push([`[${pos}] 单据 ${id}：${status}`, outcome.header, ...outcome.lines].join('\n'));
4499	  });
4500	
4501	  // 全部项通过：有新生效单据时整批一次性保存；全部重复则不改写数据
4502	  ledger.commit(dataDir);
4503	
4504	  console.log(`整批导入完成：共 ${requests.length} 项，首次生效 ${newCount} 项，重复 ${requests.length - newCount} 项。`);
4505	  for (const block of blocks) console.log(block);
4506	}
